import json
from datetime import datetime

# Read raw market data
with open('agents/data-collector/inbox/raw_market_data.json', 'r') as f:
    data = json.load(f)

# Extract competitor info
competitors = {
    "source": "raw_market_data.json",
    "extracted_at": datetime.now().isoformat(),
    "market": data.get("market", "unknown"),
