      "keystrokes": "python3 << 'EOF'
import json
from datetime import datetime

# Read competitor data
with open('agents/analyst/inbox/competitors.json', 'r') as f:
    data = json.load(f)

competitors = data['competitors']

# Analyze and identify trends
trends = [
    {
        "rank": 1,
        "trend": "Rapid Growth Among Challengers",
        "description": "Smaller competitors are experiencing significantly higher growth rates than market leaders.",
        "evidence": {
            "DeltaCloud_growth": "42.3% (highest)",
            "GammaSystems_growth": "31.8% (second highest)",
            "BetaTech_growth": "24.1%",
            "AlphaCorp_growth": "18.5% (lowest despite largest market share)"
        },
        "insight": "Market leaders with high market share (AlphaCorp at 34.2%) are growing slower than emerging players, suggesting market disruption."
    },
    {
        "rank": 2,
        "trend": "AI and ML Product Expansion",
        "description": "Competitors are aggressively adding AI/ML capabilities to their product portfolios.",
        "evidence": {
            "AlphaCorp": "AlphaAI in product lineup",
            "BetaTech": "BetaML offering",
            "GammaSystems": "Limited AI offerings (weakness)",
            "DeltaCloud": "DeltaStream (data processing)"
        },
        "insight": "AI/ML capabilities are becoming a competitive necessity, with companies lacking them at a disadvantage."
    },
    {
        "rank": 3,
        "trend": "Specialization vs. Generalization Strategy",
        "description": "Market shows clear split between broad platform providers and specialized solutions.",
        "evidence": {
            "generalists": "AlphaCorp, BetaTech - broad product range",
            "specialists": "GammaSystems (security/compliance), DeltaCloud (niche focus)",
            "specialist_advantage": "Higher growth rates (31.8%, 42.3%)",
            "generalist_challenge": "Complex onboarding, high pricing"
        },
        "insight": "Specialized players are outpacing generalists in growth, suggesting customers value focused solutions."
    }
]

# Save trends output
output = {
    "source": "competitors.json",
    "analyzed_at": datetime.now().isoformat(),
    "market": data['market'],
    "year": data['year'],
    "total_competitors_analyzed": len(competitors),
    "top_trends": trends
}

with open('agents/analyst/outbox/trends.json', 'w') as f:
    json.dump(output, f, indent=2)

# Update status
status = {
    "state": "completed",
    "started": datetime.now().isoformat(),
    "completed": datetime.now().isoformat(),
    "error": None,
    "progress": {
        "current_step": "analysis_complete",
        "steps_completed": 3,
        "total_steps": 3
    },
    "metrics": {
        "files_processed": 1,
        "outputs_generated": 1
    }
}
with open('agents/analyst/status.json', 'w') as f:
    json.dump(status, f, indent=2)

print("Analyst completed: identified 3 trends")
EOF
